<?php
require_once __DIR__.'/config.php';require_login();$q=trim($_GET['q']??'');$status=trim($_GET['status']??'');$sql="SELECT id,employee_no,first_name,middle_name,last_name,department,position_title,employment_status FROM employees WHERE (employee_no LIKE CONCAT('%',?,'%') OR first_name LIKE CONCAT('%',?,'%') OR last_name LIKE CONCAT('%',?,'%') OR department LIKE CONCAT('%',?,'%'))";if($status!=='')$sql.=' AND employment_status=?';$sql.=' ORDER BY last_name,first_name LIMIT 500';$s=$db->prepare($sql);if($status!=='')$s->bind_param('sssss',$q,$q,$q,$q,$status);else$s->bind_param('ssss',$q,$q,$q,$q);$s->execute();$rows=$s->get_result();
page_header('Employees');show_flash();echo '<h1>Employee records</h1><div class="card no-print"><form method="get" class="form-grid"><div><label>Search</label><input name="q" value="'.h($q).'" placeholder="Employee no., name, department"></div><div><label>Status</label><select name="status"><option value="">All statuses</option>';foreach(['Permanent','Temporary','Contractual','Casual','Job Order','Contract of Service','Resigned','Retired','Separated'] as $v)echo '<option '.($status===$v?'selected':'').' value="'.h($v).'">'.h($v).'</option>';echo '</select></div><div class="actions" style="align-self:end"><button>Search</button><a class="btn muted-btn" href="employees.php">Reset</a></div></form></div><div class="actions no-print">';
if(in_array($_SESSION['role'],['admin','hr'],true))echo '<a class="btn" href="employee_form.php">+ Add employee</a>';echo '<button class="muted-btn" onclick="window.print()">Print list</button></div><div class="card table-wrap"><table><tr><th>Employee No.</th><th>Name</th><th>Department / Position</th><th>Status</th><th class="no-print">Actions</th></tr>';
while($e=$rows->fetch_assoc()){echo '<tr><td>'.h($e['employee_no']).'</td><td>'.h($e['last_name'].', '.$e['first_name'].' '.$e['middle_name']).'</td><td>'.h($e['department']).'<br>'.h($e['position_title']).'</td><td>'.h($e['employment_status']).'</td><td class="no-print"><a href="employee_form.php?id='.(int)$e['id'].'">View / Edit</a>';if(in_array($_SESSION['role'],['admin','hr'],true))echo ' · <a href="employee_delete.php?id='.(int)$e['id'].'">Delete</a>';echo '</td></tr>';}echo '</table><p class="muted">Showing up to 500 results.</p></div>';page_footer();